import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1_000_000_007L;
        int n = nextInt(), k = nextInt();
        if (k == 1) {
            System.out.println(0);
            return;
        }
        // counts[i]: strings of length i without k equal letters in a row
        long[] counts = new long[n + 1];
        counts[0] = 1;
        for (int i = 1; i <= n; i++) {
            counts[i] = 26 * counts[i - 1] % MOD;
            if (i == k) counts[i] = (counts[i] - 26 + MOD) % MOD;
            else if (i > k) counts[i] = ((counts[i] - 25 * counts[i - k]) % MOD + MOD) % MOD;
        }
        System.out.println(counts[n]);
    }
}

