import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	const MOD = 1000000007
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), int(nextInt())
	if k == 1 {
		fmt.Println(0)
		return
	}
	// counts[i]: strings of length i without k equal letters in a row
	counts := make([]int64, n+1)
	counts[0] = 1
	for i := 1; i <= n; i++ {
		counts[i] = 26 * counts[i-1] % MOD
		if i == k {
			counts[i] = (counts[i] - 26 + MOD) % MOD
		} else if i > k {
			counts[i] = ((counts[i]-25*counts[i-k])%MOD + MOD) % MOD
		}
	}
	fmt.Println(counts[n])
}
